    {
      "symbol": "🕸️",
      "tooltip": "Deep learning is like a spiderweb, it vibrates unpredictably across the entire structure when a single thread is pulled or patched."
    },
    {
      "symbol": "🧪",
      "tooltip": "Unverified deployment is like a live experiment, it uses the public as non-consenting test subjects to locate system flaws."
    }
  ],
